// Media cases: the canvas's image and video nodes generate the pictures and the clip in the same run, and the build
// lays them out. createOfficialDocument wires each media node into the build as a soft `media_<id>` input that lists
// the stored files as `<node id>/<file name>` paths; the case dialog shows the published page with those files inlined.
const MEDIA_RULES = l('\n素材规则：画布里的媒体节点生成的图片和视频，以「<节点 id>/<文件名>」的相对路径列在输入里；它们是这张画布自己的文件，不算外部图片或视频。必须原样使用这些路径，并且只写在 <img src>、<video src> 或 <source src>、video 的 poster、CSS 的 url() 里——AwwO 的预览会把这些路径换成真实文件；不要在 JS 字符串里拼接或改写这些路径（那样不会被替换），JS 需要图片时，从页面里显示它的 <img> 元素读取。视频一律 muted autoplay loop playsinline，并用 object-fit: cover 铺满。绝不编造输入里没有的文件名；某个文件没有生成时，用渐变与粒子代替它，页面照常可用。画面标准：电影海报和顶级品牌官网的水准，大面积使用这些素材本身，叠加精致的中英文排版、渐变遮罩、光晕、粒子与转场动效；内容用全屏分幕切换，一打开就自动开始动效。这张页面不需要三维画面。',
  '\nMedia: the pictures and the clip the canvas’s media nodes generated are listed in the inputs by their relative paths, `<node id>/<file name>`; they are this canvas’s own files, not external images or video. Use those paths exactly as given, and only in <img src>, <video src> or <source src>, a video’s poster or a CSS url() — AwwO’s preview replaces them with the real files; never build or rewrite them in JavaScript strings (they would not be replaced), and when script needs a picture, read it from the <img> element that shows it. Every video is muted autoplay loop playsinline and fills its frame with object-fit: cover. Never invent a file name the inputs do not list; where a file was not generated, a gradient with particles stands in for it and the page still works. The look is a film poster or a leading brand’s site: the media themselves fill the screen, under refined Chinese and English typography, gradient masks, glow, particles and transitions; the content moves in full-screen acts and starts animating as soon as the page opens. This page needs no 3D.');
const mediaBuild = (zh: string, en: string) => build(zh + MEDIA_RULES.zh, en + MEDIA_RULES.en);
const CLIP: OfficialMediaNode['params'] = { aspectRatio: '16:9', duration: 5, resolution: '720p', generateAudio: false, thinking: false };
const WIDE: OfficialMediaNode['params'] = { aspectRatio: '16:9', resolution: '2K' };
const PORTRAIT: OfficialMediaNode['params'] = { aspectRatio: '3:4', resolution: '2K' };
const media = (id: string, kind: 'image' | 'video', title: Localized, row: number, prompt: Localized, params = kind === 'video' ? CLIP : WIDE): OfficialMediaNode =>
  ({ id, kind, title, prompt, model: kind === 'video' ? 'xt.xtasy-v3' : 'xt.seedream-5-pro', params, column: 0, row, feeds: ['page'] });
